insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('lentille', 'lentille', array[]::text[], 'list', $r$[{"title":"Petit salé aux lentilles","intro":"Du petit salé et des saucisses mijotés avec des lentilles vertes et des carottes.","minutes":90,"calories":680,"difficulty":"Facile","imageSearch":"pork lentils stew","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"petit salé","plural":"petit salé","qty":800,"unit":"g","have":false},{"name":"saucisse de Morteau","plural":"saucisses de Morteau","qty":1,"unit":"","have":false},{"name":"lentille verte","plural":"lentilles vertes","qty":400,"unit":"g","have":false},{"name":"carotte","plural":"carottes","qty":3,"unit":"","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"clou de girofle","plural":"clous de girofle","qty":2,"unit":"","have":false},{"name":"bouquet garni","plural":"bouquets garnis","qty":1,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais dessaler le petit salé 1 h dans l'eau froide, ou blanchis-le 10 min.","timer":{"label":"Cuisson","min":10}},{"text":"Mets-le dans une cocotte avec l'oignon piqué des clous, le bouquet garni, couvre d'eau et cuis 45 min.","timer":{"label":"Cuisson","min":45}},{"text":"Ajoute les lentilles, les carottes en rondelles et la saucisse piquée, et cuis 30 min.","timer":{"label":"Cuisson","min":30}},{"text":"Poivre et sers bien chaud.","timer":null}]},{"title":"Dal de lentilles corail","intro":"Des lentilles corail fondantes, au lait de coco et aux épices douces.","minutes":30,"calories":380,"difficulty":"Facile","imageSearch":"red lentil dal","veg":true,"oven":false,"cold":false,"missing":"","origin":"Plat indien","serves":4,"items":[{"name":"lentille corail","plural":"lentilles corail","qty":250,"unit":"g","have":false},{"name":"lait de coco","plural":"lait de coco","qty":20,"unit":"cl","have":fal