Search":"minestrone pesto","veg":true,"oven":false,"cold":false,"missing":"","origin":"Plat italien","serves":4,"items":[{"name":"carotte","plural":"carottes","qty":2,"unit":"","have":false},{"name":"courgette","plural":"courgettes","qty":1,"unit":"","have":false},{"name":"haricot vert","plural":"haricots verts","qty":150,"unit":"g","have":false},{"name":"pomme de terre","plural":"pommes de terre","qty":1,"unit":"","have":false},{"name":"coquillette","plural":"coquillettes","qty":80,"unit":"g","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"bouillon de légumes","plural":"bouillons de légumes","qty":1,"unit":"","have":false},{"name":"pesto","plural":"pesto","qty":4,"unit":"c. à s.","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":1,"unit":"c. à s.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais revenir l'oignon et les carottes dans l'huile 5 min.","timer":{"label":"Cuisson","min":5}},{"text":"Ajoute la pomme de terre, la courgette, les haricots verts coupés, 1 l d'eau et le bouillon. Cuis 20 min.","timer":{"label":"Cuisson","min":20}},{"text":"Ajoute les pâtes et cuis 10 min.","timer":{"label":"Cuisson","min":10}},{"text":"Sers avec une cuillère de pesto par bol.","timer":null}]}]$r$::jsonb, 'claude')
