insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('avocat', 'avocat', array[]::text[], 'list', $r$[{"title":"Guacamole","intro":"L'avocat écrasé au citron vert, avec tomate, oignon et coriandre.","minutes":10,"calories":180,"difficulty":"Facile","imageSearch":"guacamole","veg":true,"oven":false,"cold":true,"missing":"","origin":"Recette mexicaine","serves":4,"items":[{"name":"avocat","plural":"avocats","qty":3,"unit":"","have":false},{"name":"citron vert","plural":"citrons verts","qty":1,"unit":"","have":false},{"name":"tomate","plural":"tomates","qty":1,"unit":"","have":false},{"name":"oignon rouge","plural":"oignons rouges","qty":0.5,"unit":"","have":false},{"name":"coriandre","plural":"coriandre","qty":null,"unit":"","have":false},{"name":"piment","plural":"piments","qty":1,"unit":"","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false}],"steps":[{"text":"Écrase la chair des avocats à la fourchette avec le jus du citron vert.","timer":null},{"text":"Ajoute la tomate en petits dés et l'oignon haché fin.","timer":null},{"text":"Ajoute la coriandre ciselée et un peu de piment.","timer":null},{"text":"Sale, mélange et sers tout de suite avec des chips de maïs.","timer":null}]},{"title":"Poke bowl au saumon","intro":"Du riz vinaigré, du saumon cru mariné au soja, de l'avocat, du concombre et du sésame.","minutes":25,"calories":580,"difficulty":"Facile","imageSearch":"salmon poke bowl","veg":false,"oven":false,"cold":true,"missing":"","origin":"Plat hawaïen","serves":4,"items":[{"name":"riz à sushi","plural":"riz à sushi","qty":250,"unit":"g","have":false},{"name":"pavé de saumon extra-frais","plural":"pavés de saumon extra-frais","qty":2,"unit":"","have":false},{"name":"avocat","plural":"avocats","qty":1,"unit":"","have":false},{"name":"concombre","plural":"concombres","qty":0.5,"unit":"","have":false},{"name":"edamame","plural":"edamame","qty":100,"unit":"g","have":false},{"name":"sauce soja","plural":"sauce soja","qty":3,"unit":"c. à s.","have":false},{"name":"vinaigre de riz","plural":"vinaigre de riz","qty":2,"unit":"c. à s.","have":false},{"name":"graines de sésame","plural":"graines de sésame","qty":1,"unit":"c. à s.","have":false},{"name":"oignon nouveau","plural":"oignons nouveaux","qty":1,"unit":"","have":false}],"steps":[{"text":"Fais cuire le riz, puis mélange-le avec le vinaigre de riz et laisse tiédir.","timer":{"label":"Cuisson","min":15}},{"text":"Coupe le saumon en cubes et fais-le mariner 10 min dans la sauce soja.","timer":{"label":"Marinade","min":10}},{"text":"Coupe l'avocat et le concombre.","timer":null},{"text":"Dans des bols, mets le riz, le saumon, les légumes, les edamame, le sésame et l'oignon.","timer":null}]},{"title":"Avocado toast","intro":"Du pain grillé, de l'avocat écrasé au citron et une pointe de piment.","minutes":10,"calories":280,"difficulty":"Facile","imageSearch":"avocado toast","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"pain complet","plural":"pains complets","qty":4,"unit":"tranches","have":false},{"name":"avocat","plural":"avocats","qty":2,"unit":"","have":false},{"name":"citron","plural":"citrons","qty":0.5,"unit":"","have":false},{"name":"piment d'Espelette","plural":"piment d'Espelette","qty":null,"unit":"","have":false},{"name":"graines de sésame","plural":"graines de sésame","qty":1,"unit":"c. à c.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais griller le pain.","timer":null},{"text":"Écrase les avocats avec le jus du citron et le sel.","timer":null},{"text":"Tartine et parsème de piment et de sésame.","timer":null}]},{"title":"Buddha bowl","intro":"Un bol complet et coloré : quinoa, pois chiches rôtis, légumes, avocat et sauce au tahin.","minutes":35,"calories":560,"difficulty":"Facile","imageSearch":"buddha bowl","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"quinoa","plura