insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('parmesan', 'parmesan', array[]::text[], 'list', $r$[{"title":"Spaghetti bolognaise","intro":"Une sauce tomate à la viande mijotée tranquillement, sur des spaghetti al dente.","minutes":50,"calories":620,"difficulty":"Facile","imageSearch":"spaghetti bolognese","veg":false,"oven":false,"cold":false,"missing":"","origin":"Plat italien","serves":4,"items":[{"name":"spaghetti","plural":"spaghetti","qty":400,"unit":"g","have":false},{"name":"bœuf haché","plural":"bœuf haché","qty":400,"unit":"g","have":false},{"name":"tomate concassée","plural":"tomates concassées","qty":800,"unit":"g","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"carotte","plural":"carottes","qty":1,"unit":"","have":false},{"name":"ail","plural":"ails","qty":2,"unit":"gousse","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":2,"unit":"c. à s.","have":false},{"name":"origan","plural":"origan","qty":null,"unit":"","have":false},{"name":"parmesan râpé","plural":"parmesan râpé","qty":40,"unit":"g","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais revenir l'oignon, la carotte en petits dés et l'ail dans l'huile 5 min.","timer":{"label":"Cuisson","min":5}},{"text":"Ajoute la viande et fais-la dorer 5 min en l'émiettant.","timer":{"label":"Cuisson","min":5}},{"text":"Verse les tomates, ajoute l'origan, sale et poivre, et laisse mijoter 30 min.","timer":{"label":"Mijotage","min":30}},{"text":"Fais cuire les spaghetti dans l'eau bouillante salée selon le paquet.","timer":{"label":"Pâtes","min":10}},{"text":"Sers la sauce sur les pâtes avec le parmesan.","timer":null}],"kids":true},{"title":"Boulettes de bœuf à la sauce tomate","intro":"Des boulettes moelleuses, mijotées dans une sauce tomate au basilic.","minutes":40,"calories":520,"difficul