insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('quinoa', 'quinoa', array[]::text[], 'list', $r$[{"title":"Salade de quinoa","intro":"Du quinoa avec concombre, tomates, feta et herbes, comme un taboulé.","minutes":25,"calories":380,"difficulty":"Facile","imageSearch":"quinoa salad","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"quinoa","plural":"quinoa","qty":200,"unit":"g","have":false},{"name":"concombre","plural":"concombres","qty":1,"unit":"","have":false},{"name":"tomate cerise","plural":"tomates cerises","qty":250,"unit":"g","have":false},{"name":"feta","plural":"fetas","qty":150,"unit":"g","have":false},{"name":"menthe fraîche","plural":"menthe fraîche","qty":null,"unit":"","have":false},{"name":"citron","plural":"citrons","qty":1,"unit":"","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":3,"unit":"c. à s.","have":false}],"steps":[{"text":"Rince le quinoa, puis fais-le cuire 12 min à l'eau salée. Égoutte et laisse refroidir.","timer":{"label":"Cuisson","min":12}},{"text":"Coupe le concombre en dés et les tomates en deux.","timer":null},{"text":"Mélange avec le quinoa, la feta émiettée et la menthe ciselée.","timer":null},{"text":"Assaisonne de jus de citron et d'huile d'olive.","timer":null}]},{"title":"Buddha bowl","intro":"Un bol complet et coloré : quinoa, pois chiches rôtis, légumes, avocat et sauce au tahin.","minutes":35,"calories":560,"difficulty":"Facile","imageSearch":"buddha bowl","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"quinoa","plural":"quinoa","qty":200,"unit":"g","have":false},{"name":"pois chiche","plural":"pois chiches","qty":250,"unit":"g","have":false},{"name":"patate douce","plural":"patates douces","qty":1,"unit":"","have":false},{"name":"avocat","plural":"avocats","qty":1,"unit":"","have":false},{"name":"chou rouge","plural":"choux rouges","qty":0.25,"unit":"","have":false},{"name":"carotte","plural":"carottes","qty":2,"unit":"","have":false},{"name":"tahin","plural":"tahin","qty":3,"unit":"c. à s.","have":false},{"name":"citron","plural":"citrons","qty":1,"unit":"","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":2,"unit":"c. à s.","have":false},{"name":"paprika","plural":"paprika","qty":1,"unit":"c. à c.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false}],"steps":[{"text":"Préchauffe le four à 200 °C. Mets la patate douce en cubes et les pois chiches sur une plaque avec l'huile, le paprika et le sel. Enfourne 25 min.","timer":{"label":"Four","min":25}},{"text":"Fais cuire le quinoa 12 min.","timer":{"label":"Cuisson","min":12}},{"text":"Mélange le tahin, le jus du citron et un peu d'eau pour la sauce.","timer":null},{"text":"Monte les bols avec le quinoa, les légumes râpés, l'avocat, les pois chiches et la patate douce, puis la sauce.","timer":null}]},{"title":"Taboulé au quinoa","intro":"Le taboulé frais, au quinoa.","minutes":25,"calories":330,"difficulty":"Facile","imageSearch":"quinoa tabbouleh","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"quinoa","plural":"quinoa","qty":200,"unit":"g","have":false},{"name":"tomate","plural":"tomates","qty":3,"unit":"","have":false},{"name":"concombre","plural":"concombres","qty":0.5,"unit":"","have":false},{"name":"poivron rouge","plural":"poivrons rouges","qty":1,"unit":"","have":false},{"name":"menthe","plural":"menthe","qty":null,"unit":"","have":false},{"name":"citron","plural":"citrons","qty":2,"unit":"","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":4,"unit":"c. à s.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais cuire le quinoa 12 min dans l'eau salée et laisse-le refroidir.","timer":{"label":"Cuisson","min":12}},{"text":"Coupe les légumes en petits dés.","timer":null},{"text":"Mélange avec le quinoa, la menthe, le jus des citrons, l'huile, sel et poivre.","timer":null}]},{"title":"Salade de quinoa à l'avocat","intro":"Une salade de quinoa à la mexicaine, complète et vegan.","minutes":25,"calories":450,"difficulty":"Facile","imageSearch":"quinoa avocado black bean salad","veg":true,"oven":false,"cold":true,"missing":"","origin":"Inspiration mexicaine","serves":4,"items":[{"name":"quinoa","plural":"quinoa","qty":200,"unit":"g","have":false},{"name":"avocat","plural":"avocats","qty":2,"unit":"","have":false},{"name":"haricots rouges","plural":"haricots rouges","qty":250,"unit":"g","have":false},{"name":"maïs","plural":"maïs","qty":140,"unit":"g","have":false},{"name":"citron vert","plural":"citrons verts","qty":2,"unit":"","have":false},{"name":"coriandre","plural":"coriandre","qty":null,"unit":"","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":3,"unit":"c. à s.","have":false}],"steps":[{"text":"Fais cuire le quinoa 12 min, égoutte et laisse refroidir.","timer":{"label":"Cuisson","min":12}},{"text":"Rince les haricots rouges et le maïs.","timer":null},{"text":"Coupe les avocats en dés et arrose-les de jus de citron vert.","timer":null},{"text":"Mélange tout avec la coriandre, l'huile et le reste du jus.","timer":null}]},{"title":"Salade de quinoa au poulet","intro":"La salade de quinoa en plat complet, avec du poulet.","minutes":30,"calories":470,"difficulty":"Facile","imageSearch":"quinoa chicken salad","veg":false,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"quinoa","plural":"quinoa","qty":200,"unit":"g","have":false},{"name":"blanc de poulet","plural":"blancs de poulet","qty":2,"unit":"","have":false},{"name":"concombre","plural":"concombres","qty":1,"unit":"","have":false},{"name":"tomate cerise","plural":"tomates cerises","qty":250,"unit":"g","have":false},{"name":"citron","plural":"citrons","qty":1,"unit":"","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":3,"unit":"c. à s.","have":false}],"steps":[{"text":"Fais cuire le quinoa 12 min, égoutte et laisse refroidir.","timer":{"label":"Cuisson","min":12}},{"text":"Fais griller le poulet 6 min de chaque côté et coupe-le en lamelles.","timer":{"label":"Poêle","min":12}},{"text":"Coupe le concombre et les tomates.","timer":null},{"text":"Mélange tout avec le jus de citron et l'huile.","timer":null}]}]$r$::jsonb, 'claude')
